#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  int r;  POINT pt[5];  } Queue_Romb;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintRomb(DefinePaint)  {  QueueP(Queue_Romb);  if ( p->r != 0 )    ::Polygon( hDC, p->pt, 4 );  else    ::Polyline( hDC, p->pt, 5 );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddRomb(DefineTegs)  {  AddQueueEx(Queue_Romb);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintRomb;  //  STegObj obj[] =    {    { 'R', "rect", &p->mRect },    { 'E', "rc"  , &p->mRect },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  p->r = Atoi(teg[0].value);  //  int cx = (p->mRect.left + p->mRect.right)/2;  int cy = (p->mRect.top + p->mRect.bottom)/2;  p->pt[0].x = cx,p->pt[0].y = p->mRect.top;  p->pt[3].y = cy,p->pt[3].x = p->mRect.left;  p->pt[1].y = cy,p->pt[1].x = p->mRect.right;  p->pt[2].x = cx,p->pt[2].y = p->mRect.bottom;  p->pt[4] = p->pt[0];  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~